<?php
require_once '../config/koneksi.php';require_once '../config/auth.php';require_admin();
$key=trim($_GET['q']??'');$rows=null;
if($key!==''){$like='%'.strtoupper($key).'%';$stmt=mysqli_prepare($conn,"SELECT p.tanggal,k.merk,k.nomor_polisi,d.nama driver,pr.jam_ambil,pr.jam_pulang,pr.km_awal,pr.km_akhir,p.status,p.tujuan FROM penugasan p JOIN kendaraan k ON k.id=p.kendaraan_id JOIN drivers d ON d.id=p.driver_id LEFT JOIN perjalanan pr ON pr.penugasan_id=p.id WHERE UPPER(k.nomor_polisi) LIKE ? ORDER BY p.tanggal DESC,p.id DESC");mysqli_stmt_bind_param($stmt,'s',$like);mysqli_stmt_execute($stmt);$rows=mysqli_stmt_get_result($stmt);}
$page_title='Cari Kendaraan';require '../partials/header.php';require '../partials/navbar.php';?>
<div class="main-wrap"><?php require '../partials/sidebar.php';?><main class="content"><h3>Cari Kendaraan</h3><p class="text-muted">Cari histori berdasarkan nomor polisi.</p><div class="card card-stat p-3 mb-3"><form class="input-group input-group-lg"><input class="form-control" name="q" data-uppercase value="<?=e($key)?>" placeholder="Contoh: L 1439 BDE"><button class="btn btn-bj">Cari</button></form></div>
<?php if($rows):?><div class="card card-stat"><div class="card-body table-responsive"><table class="table"><thead><tr><th>Tanggal</th><th>Kendaraan</th><th>Plat</th><th>Driver</th><th>Masuk</th><th>Keluar</th><th>KM</th><th>Status</th></tr></thead><tbody><?php while($r=mysqli_fetch_assoc($rows)):?><tr><td><?=e(date('d-m-Y',strtotime($r['tanggal'])))?></td><td><?=e($r['merk'])?></td><td><b><?=e($r['nomor_polisi'])?></b></td><td><?=e($r['driver'])?></td><td><?=e($r['jam_ambil']?:'-')?></td><td><?=e($r['jam_pulang']?:'-')?></td><td><?=e(($r['km_awal']??'-').' → '.($r['km_akhir']??'-'))?></td><td><?=e($r['status'])?></td></tr><?php endwhile;?></tbody></table></div></div><?php elseif($key!==''):?><div class="alert alert-warning">Nomor kendaraan <b><?=e($key)?></b> belum memiliki histori.</div><?php endif;?></main></div><?php require '../partials/footer.php';?>
